contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        uint b0 = address(this).balance;
        uint p0 = c.pot();
        bool reverted;
        try c.play{value: amount}() { reverted = false; } catch { reverted = true; }
        uint b1 = address(this).balance;
        uint p1 = c.pot();
        // General rule: a revert must be fully inert (no pot change, no ether moved).
        // A successful play costs exactly 10 wei; if the pot is not reset (loss),
        // pot grows by exactly 10 and the caller paid exactly 10; if the pot is
        // reset (win), the caller's balance is exactly restored (payout pot-1 to
        // player plus 1 fee to bank, both being this contract in full).
        assert(
            reverted
                ? (b1 == b0 && p1 == p0)
                : (
                    p1 == 0
                        ? b1 == b0 + p0
                        : (b1 + 10 == b0 && p1 == p0 + 10)
                  )
        );
    }

    receive() external payable {}
}

