        uint p0 = c.pot();
        bool reverted;
        try c.play{value: amount}() { reverted = false; } catch { reverted = true; }
        uint b1 = address(this).balance;
        uint cBal1 = address(c).balance;
        uint p1 = c.pot();
        // Rule: no value can vanish. A revert is fully inert (no ether moves, pot unchanged).
        // A successful play first transfers exactly `amount` into c (pot grows by amount,
        // since amount must equal TICKET_AMOUNT to pass the require), then any payout
        // transfers ether only between c and this contract, so total holdings are
        // conserved minus exactly the ticket amount paid in.
        assert(
            reverted
                ? (b1 == b0 && cBal1 == cBal0 && p1 == p0)
                : (b1 + cBal1 + amount == b0 + cBal0)
        );
    }

    receive() external payable {}
}

