            assert(
                (potAfter == potBefore + 10 && balanceAfter == balanceBefore + 10) ||
                (potAfter == 0 && balanceAfter == balanceBefore - (potBefore + 10) + (potBefore + 10) && balanceAfter + potBefore + 10 == balanceBefore + potBefore + 10) ||
                balanceAfter == potAfter
            );
        }
        assert(address(c).balance == c.pot());
    }
    receive() external payable {}
}

